  const a = tuNut(x), b = tuNut(y);
  if (a.length < 2 || b.length < 2 || a.join(' ') === b.join(' ')) return false;
  const [n, d] = a.length <= b.length ? [a, b] : [b, a]; let i = 0;
  for (const w of d) if (w === n[i]) i++;
